// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address attacker = address(0x1234);
        address receiver = address(0x5678);
        uint amount = 1 ether;

        // Fund attacker
        vm.deal(attacker, amount);
        // Try to send as attacker (not owner)
        vm.prank(attacker);
        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: ok == false (revert because not owner)
        // Bug: ok == true (no owner check, transfer succeeds)
        assertTrue(ok == false);
    }
}

