        uint256 balanceBefore = address(c).balance;

        vm.prank(nonOwner);
        // This call will revert in the reference, but succeed in the buggy version
        try c.sendTo(receiver, amount) {
            // If no revert, then bug version executed
        } catch {
            // Expected revert for reference; we still check balance
        }

        uint256 balanceAfter = address(c).balance;
        // Reference: revert => no ether sent, balance unchanged => balanceAfter == balanceBefore
