pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: owner has ether, contract has some balance
        vm.deal(address(this), 10 ether);
        vm.deal(address(c), 1 ether);

        // Call sendTo from owner (the test contract is owner after deployment via constructor)
        // Try to send 1 wei to address(0) - this should revert in reference but not in buggy
        bool ok;
        try c.sendTo(address(0), 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference reverts (ok = false), the buggy version succeeds (ok = true)
        // We assert that the call reverted - this holds for reference, fails for buggy
        assertTrue(!ok, "sendTo should revert when receiver is address(0)");
    }
}

