pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: owner is the contract deployer (this test contract)
        // Give owner some ether to send
        vm.deal(address(this), 1 ether);

        // Record owner balance before the call
        uint256 ownerBalanceBefore = address(this).balance;

        // Attempt to send 0 wei to a random address
        address receiver = address(0x1234);

        // The reference contract reverts because amount > 0 is required
        // But the buggy contract does not revert
        bool success;
        try c.sendTo(receiver, 0) {
            success = true;
        } catch {
            success = false;
        }

        // On the reference contract, success is false (revert)
        // On the buggy contract, success is true (no revert) and ether is actually transferred
        // Assert that the call succeeded (which is true for the buggy version, false for reference)
        // Since we want the test to PASS on reference and FAIL on buggy,
        // we assert the reference behavior: success should be false
        assertTrue(!success);
    }
}

